<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {useSubjectiveAttempt} from '@/stores/practice-subjective'
import {reviseSubjective} from '@/api/practice-subjective'
import {errorMessage} from '@/api/identity'
import {getGeneration} from '@/auth/token-session'
import {useAutomaticPracticeReview} from '@/stores/practice-auto-review'
import PracticeSubjectiveTools from '@/components/practice/PracticeSubjectiveTools.vue'
import '@/styles/practice.css'
import '@/styles/practice-subjective.css'
const route=useRoute(),router=useRouter(),store=useSubjectiveAttempt(),error=ref(''),revising=ref(false);let reviseId='',disposed=false
const label=computed(()=>store.attempt?.readingType==='TRANSLATION'?'翻译':'写作'),done=computed(()=>store.attempt?.status==='COMPLETED'),destination=computed(()=>{const p=String(route.query.returnTo||'');return /^\/practice(?:\?|\/(?:cet|cet4|postgraduate)(?:\?|$))/.test(p)?p:'/practice'})
const outOfRange=computed(()=>{const p=store.attempt?.prompt;return p?.minWords!=null&&(store.wordCount<p.minWords||store.wordCount>p.maxWords!)})
const automaticReview=useAutomaticPracticeReview()
watch(()=>done.value?store.attempt?.id:'',()=>{const a=store.attempt;if(done.value&&a)automaticReview.enqueue([{sourceType:'SUBJECTIVE',attemptId:a.id,slot:a.readingType}])})
async function submit(){if(!await store.flush())return;try{await ElMessageBox.confirm(outOfRange.value?'当前词数超出建议范围，仍要提交吗？提交后将题目与本次作答发送至 DeepSeek 自动评分，使用现有批改额度。':'确认提交本次作答？题目与本次作答将发送至 DeepSeek 自动评分，使用现有批改额度，并保留本次记录。','提交作答',{confirmButtonText:'确认提交',cancelButtonText:'继续检查',autofocus:false})}catch{return}await store.submit(outOfRange.value)}
async function clearText(){try{await ElMessageBox.confirm('清空当前草稿？此前的提交记录仍保留。','清空草稿',{confirmButtonText:'清空草稿',cancelButtonText:'取消',autofocus:false})}catch{return}store.edit('');await store.flush()}
async function leave(){if(store.submitting||revising.value||store.pendingSubmit){error.value='请求结果尚未确认，请先重试或重新读取本轮状态。';return false}if(store.recoveryText){try{await ElMessageBox.confirm('仍有保留的本地文字，请先复制或用它创建修改稿。现在离开将丢弃这份本地副本。','保留文字尚未保存',{confirmButtonText:'丢弃副本并离开',cancelButtonText:'返回保留文字',autofocus:false})}catch{return false}}return await store.flush()}
async function revise(){if(!store.attempt||revising.value)return;const g=getGeneration();revising.value=true;error.value='';reviseId||=crypto.randomUUID();try{const a=await reviseSubjective(store.attempt.id,reviseId);if(!disposed&&g===getGeneration()){reviseId='';store.carryRecovery(a.id);revising.value=false;await router.push({path:'/practice/subjective-attempts/'+a.id,query:{returnTo:destination.value}})}}catch(e){if(!disposed&&g===getGeneration())error.value=errorMessage(e)}finally{revising.value=false}}
function unload(e:BeforeUnloadEvent){if(store.dirty||store.saving||store.pendingSubmit||store.recoveryText){e.preventDefault();e.returnValue=''}}
watch(()=>route.params.id,()=>{error.value='';reviseId='';void store.load(String(route.params.id))},{immediate:true})
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);window.addEventListener('beforeunload',unload)
onBeforeUnmount(()=>{disposed=true;store.dispose();window.removeEventListener('beforeunload',unload)})
</script>
<template><section class="practice-page practice-subjective"><header class="subjective-header"><RouterLink class="reading-back practice-back" :to="destination">← 返回练习列表</RouterLink><span v-if="store.attempt" class="practice-tag">{{label}} · {{done?'已提交':'草稿'}}</span></header><p v-if="store.loading" role="status">正在加载练习…</p><p v-if="store.error||error" role="alert" class="practice-notice practice-error">{{store.error||error}}</p><div v-if="store.conflict" class="practice-notice"><p>其他页面已更新。可先复制当前文字，再读取最新状态；若仍是草稿，将保留这里的文字，供你比较后手动保存。</p><button :disabled="store.loading" @click="store.reloadKeepingText()">读取最新状态，保留本地文字</button></div><button v-if="!store.attempt&&!store.loading" @click="store.load(String(route.params.id))">重新加载</button><template v-if="store.attempt"><section v-if="store.recoveryText" class="practice-panel subjective-recovery"><h2>保留的本地文字（尚未保存）</h2><p>另一页面已提交本轮。下面保留冲突前的文字，可复制，或点击“继续修改”带入新修改稿。</p><label for="subjective-recovery">冲突前的本地文字</label><textarea id="subjective-recovery" :value="store.recoveryText" readonly/></section><h1>{{store.attempt.title}}</h1><p class="practice-hint">{{label}}练习 · 提交后自动评分（15分制学习参考），并解锁参考内容。</p><section class="subjective-prompt practice-panel"><header><h2>{{label==='写作'?'Directions':'翻译材料'}}</h2><span v-if="store.attempt.prompt.minutes" class="practice-hint">建议 {{store.attempt.prompt.minutes}} 分钟</span></header><p class="subjective-material">{{store.attempt.prompt.prompt}}</p><details v-if="store.attempt.prompt.requirements"><summary>要求与提示</summary><p class="subjective-material">{{store.attempt.prompt.requirements}}</p></details></section><section class="subjective-answer practice-panel"><header><h2>{{label==='写作'?'我的作文':'我的译文'}}</h2><span class="practice-hint"><span v-if="store.attempt.prompt.minWords!=null">建议 {{store.attempt.prompt.minWords}}–{{store.attempt.prompt.maxWords}} 词</span><span v-else>词数仅供参考</span></span></header><label class="visually-hidden" for="subjective-answer">{{label==='写作'?'英文作文':'英文译文'}}</label><textarea id="subjective-answer" :value="store.text" :readonly="done||!!store.pendingSubmit||store.submitting||store.loading" maxlength="20000" :placeholder="label==='写作'?'在这里写你的英文作文…':'Translate the passage into English…'" @input="store.edit(($event.target as HTMLTextAreaElement).value)"/><PracticeSubjectiveTools :source="done?{sourceType:'SUBJECTIVE',attemptId:store.attempt.id,slot:store.attempt.readingType}:undefined" :writing="label==='写作'" :word-count="store.wordCount" :reference="store.attempt.reference" :notes="store.attempt.notes"/><div class="subjective-save" role="status">{{done?'已提交 · '+new Date(store.attempt.completedAt!).toLocaleString():store.saveState}} <span v-if="!done">· {{store.text.length}} / 20000 字符</span></div><div class="practice-actions"><template v-if="!done"><button :disabled="store.saving||store.loading||store.submitting||store.conflict||!!store.pendingSubmit" @click="store.flush()">保存草稿</button><button :disabled="store.loading||store.submitting||!!store.pendingSubmit||store.conflict" @click="clearText">清空</button><button class="button-primary" :disabled="store.loading||store.submitting||store.conflict||!store.wordCount" @click="store.pendingSubmit?store.submit(false):submit()">{{store.submitting?'正在提交…':store.pendingSubmit?'重试确认提交':'提交作答'}}</button><button v-if="store.pendingSubmit" @click="store.reloadKeepingText()">读取服务器结果</button></template><button v-else :disabled="revising" @click="revise">{{revising?'正在创建修改稿…':'继续修改（保留本次提交）'}}</button></div></section></template></section></template>
